import{_ as l,a0 as e,w as r,s as h,ao as k,I as t,x as a,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如果使用32位整型會溢出，那麼是否可以使用一個40位結構體代替64位長整型？ | LCTT x X-CMD","titleTemplate":false,"description":"如果使用32位整型會溢出，那麼是否可以使用一個40位結構體代替64位長整型？ | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如果使用32位整型會溢出，那麼是否可以使用一個40位結構體代替64位長整型？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如果使用32位整型會溢出，那麼是否可以使用一個40位結構體代替64位長整型？ | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150121 If a 32-bit integer overflows","title":"如果使用32位整型會溢出，那麼是否可以使用一個40位結構體代替64位長整型？","tag":"201502","desc":""},"relativePath":"201502/20150121 If a 32-bit integer overflows.md","filePath":"[post].md"}'),o={name:"201502/20150121 If a 32-bit integer overflows.md"};function d(g,s,u,E,c,f){const n=e("Link");return r(),h("div",null,[s[14]||(s[14]=k(`<h1 id="如果使用32位整型會溢出-那麼是否可以使用一個40位結構體代替64位長整型" tabindex="-1">如果使用32位整型會溢出，那麼是否可以使用一個40位結構體代替64位長整型？ <a class="header-anchor" href="#如果使用32位整型會溢出-那麼是否可以使用一個40位結構體代替64位長整型" aria-label="Permalink to “如果使用32位整型會溢出，那麼是否可以使用一個40位結構體代替64位長整型？”">​</a></h1><p>###問題：</p><p>假如説，使用32位的整型會溢出，在不考慮使用長整型的情況下，如果我們只需要表示2的40次方範圍內的數，是否可以利用某些40位長的數據類型來表示呢？這樣的話，每個整型數就可以節省24位的空間。</p><p>如果可以，該怎麼做？</p><p>需求是：我現在必須處理數以億計的數字，所以在存儲空間上受到了很大的限制。</p><p>###回答：</p><p>可以是可以，但是……</p><p>這種方法的確可行，但這麼做通常沒什麼意義（因為幾乎沒有程序需要處理多達十億的數字）：</p><div class="language-C"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;stdint.h&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 不要考慮使用long long類型</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bad_idea</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> var : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>在這裏，變量var佔據40位大小，但是這是以生成代碼時擁有非常低的運行效率來換取的（事實證明“非常”二字言過其實了——測試中程序開銷僅僅增加了1%到2%，正如下面的測試時間所示），而且這麼做通常沒什麼用。除非你還需要保存一個24位的值（或者是8位、16位的值），這樣你皆可以它們放到同一個結構中。不然的話，因為對齊內存地址產生的開銷會抵消這麼做帶來的好處。</p><p>在任何情況下，除非你是真的需要保存數以億計的數字，否則這樣做給內存消耗帶來的好處是可以忽略不計的（但是為了處理這些位字段的額外代碼量是不可忽略的！）。</p><p>###説明：</p><p>在此期間，這個問題已經被更新了，是為了説明實際上確實有需要處理數以億計數字的情況。假設，採取某些措施來防止因為結構體對齊和填充抵消好處（比如在後24位中存儲其它的內容，或者使用多個8位來存儲40位），那麼這麼做就變得有意義了。</p><p>如果有十億個數，每個數都節省三個字節的空間，那麼這麼做就非常有用了。因為使用更小的空間存儲要求更少的內存頁，也就會產生更少的cache和TLB不命中和內存缺頁（單個缺頁會產生數以千萬計的指令 [譯者注：直譯是這樣，但語義説不通！]）。</p><p>儘管上面提到的情況不足以充分利用到剩餘的24位（它僅僅使用了40位部分），如果確實在剩餘位中放入了有用的數據，那麼使用類似下面的方法會使得這種思路就管理內存而言顯得非常有用。</p><div class="language-C"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> using_gaps</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> var           : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> useful_uint16 : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> char_or_bool  : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>結構體大小和對齊長度等於64位整型的大小，所以只要使用得當就不會浪費空間，比如對一個保存10億個數的數組使用這個結構（不考慮使用指定編譯器的擴展）。如果你不會用到一個8位的值，那麼你可以使用一個48位和16位的值（giving a bigger overflow margin）。</p><p>或者以犧牲可用性為代價，把8個64位的值放入這樣的結構體中（或者使用40和64的組合使得其和滿足320）。當然，在這種情況下，通過代碼去訪問數組結構體中的元素會變得非常麻煩（儘管一種方法是實現一個operator[]在功能上還原線性數組，隱藏結構體的複雜性）。</p><p>###更新：</p><p>我寫了一個快速測試工具，只是為了獲得位字段的開銷（以及伴隨位字段引用的重載操作）。由於長度限制將代碼發佈在gcc.godbolt.org上，在本人64位Win7上的測試結果如下：</p><div class="language-TXT"><button title="Copy Code" class="copy"></button><span class="lang">TXT</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>運行測試的數組大小為1048576</span></span>
<span class="line"><span>what       alloc   seq(w)  seq(r)  rand(w)  rand(r)  free</span></span>
<span class="line"><span>-----------------------------------------------------------</span></span>
<span class="line"><span>uint32_t    0      2       1       35       35       1</span></span>
<span class="line"><span>uint64_t    0      3       3       35       35       1</span></span>
<span class="line"><span>bad40_t     0      5       3       35       35       1</span></span>
<span class="line"><span>packed40_t  0      7       4       48       49       1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>運行測試的數組大小為16777216</span></span>
<span class="line"><span>what        alloc  seq(w)  seq(r)  rand(w)  rand(r)  free</span></span>
<span class="line"><span>-----------------------------------------------------------</span></span>
<span class="line"><span>uint32_t    0      38      14      560      555      8</span></span>
<span class="line"><span>uint64_t    0      81      22      565      554      17</span></span>
<span class="line"><span>bad40_t     0      85      25      565      561      16</span></span>
<span class="line"><span>packed40_t  0      151     75      765      774      16</span></span>
<span class="line"><span></span></span>
<span class="line"><span>運行測試的數組大小為134177228</span></span>
<span class="line"><span>what        alloc  seq(w)  seq(r)  rand(w)  rand(r)  free</span></span>
<span class="line"><span>-----------------------------------------------------------</span></span>
<span class="line"><span>uint32_t    0      312     100     4480     4441     65</span></span>
<span class="line"><span>uint64_t    0      648     172     4482     4490     130</span></span>
<span class="line"><span>bad40_t     0      682     193     4573     4492     130</span></span>
<span class="line"><span>packed40_t  0      1164    552     6181     6176     130</span></span></code></pre></div><p>我們看到，位字段的額外開銷是微不足道的，但是當以友好的方式線性訪問數據時伴隨位字段引用的操作符重載產生的開銷則相當顯著（大概有3倍）。在另一方面，隨機訪問產生的開銷則無足輕重。</p><p>這些時間表明簡單的使用64位整型會更好，因為它們在整體性能上要比位字段好（儘管佔用更多的內存），但是顯然它們並沒有考慮隨着數據集增大帶來的缺頁開銷。一旦程序內存超過RAM大小，結果可能就不一樣了（未親自考證）。</p><hr>`,24)),t("p",null,[s[1]||(s[1]=a("via:",-1)),i(n,{href:"http://stackoverflow.com/questions/27705409/if-a-32-bit-integer-overflows-can-we-use-a-40-bit-structure-instead-of-a-64-bit/27705562#27705562"},{default:p(()=>[...s[0]||(s[0]=[a("stackoverflow",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"http://stackoverflow.com/users/572743/damon"},{default:p(()=>[...s[2]||(s[2]=[a("Damon",-1)])]),_:1}),i(n,{href:"http://stackoverflow.com/users/5801/michael-kohne"},{default:p(()=>[...s[3]||(s[3]=[a("Michael Kohne",-1)])]),_:1}),s[7]||(s[7]=a(" 譯者：",-1)),i(n,{href:"https://github.com/KayGuoWhu"},{default:p(()=>[...s[4]||(s[4]=[a("KayGuoWhu",-1)])]),_:1}),s[8]||(s[8]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[11]||(s[11]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[9]||(s[9]=[a("LCTT",-1)])]),_:1}),s[12]||(s[12]=a(" 原創翻譯，",-1)),i(n,{href:"http://linux.cn/"},{default:p(()=>[...s[10]||(s[10]=[a("Linux中國",-1)])]),_:1}),s[13]||(s[13]=a(" 榮譽推出",-1))])])}const m=l(o,[["render",d]]);export{C as __pageData,m as default};
